begin;
select plan(24);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.approve_calendar('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',1);
select public.save_copy('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',1,'{"subject":"Original synthetic note","preheader":"Fixture","body":"A considered corner to explore.","cta":"Explore","url":"https://north-studio.example/products/vase"}');
select public.approve_copy('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',2);
select set_config('test.render_job',public.enqueue_render('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',2,2)::text,true);
select set_config('test.render_lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select throws_ok($$select public.finish_render_job(current_setting('test.render_job')::uuid,null,'{}')$$,'PT409',null,'render needs current lease');
select throws_ok($$select public.finish_render_job(current_setting('test.render_job')::uuid,current_setting('test.render_lease')::uuid,'{"synthetic":true,"strips":[{"section":"hero","path":"unverified.svg"}]}')$$,'23514',null,'text output rejects irrelevant image slicing');
select set_config('test.render_id',public.finish_render_job(current_setting('test.render_job')::uuid,current_setting('test.render_lease')::uuid,'{"synthetic":true,"strips":[]}')::text,true);
select is((select design_state from public.campaigns where id='00000000-0000-4000-8000-000000000602'),'submitted','fake orchestration does not approve its own output');
select throws_ok($$select public.review_render('00000000-0000-4000-8000-000000000102',current_setting('test.render_id')::uuid,2,'approved','whole_design','Approved')$$,'PT409',null,'unseen revision cannot be approved');
select lives_ok($$select public.review_render('00000000-0000-4000-8000-000000000102',current_setting('test.render_id')::uuid,3,'revision','copy','Improve the body spacing')$$,'owner requests section revision');
select is((select design_state from public.campaigns where id='00000000-0000-4000-8000-000000000602'),'revisions_requested','revision state persists');
select set_config('test.render_job2',public.enqueue_render('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',2,3)::text,true);
select set_config('test.render_lease2',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select set_config('test.render_id2',public.finish_render_job(current_setting('test.render_job2')::uuid,current_setting('test.render_lease2')::uuid,'{"synthetic":true,"strips":[]}')::text,true);
select lives_ok($$select public.review_render('00000000-0000-4000-8000-000000000102',current_setting('test.render_id2')::uuid,4,'approved','whole_design','Owner exact approval')$$,'owner approves exact current text design');
select throws_ok($$select public.create_delivery_package('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',4,'{}')$$,'23514',null,'missing footer blocks readiness');
select set_config('test.render_package',public.create_delivery_package('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',4,'{"senderName":"Synthetic North","senderEmail":"studio@north-studio.example","address":"Original Fictional Postal Address","unsubscribeUrl":"https://north-studio.example/unsubscribe","privacyUrl":"https://north-studio.example/privacy"}')::text,true);
select ok((select snapshot->>'html' not like '%<img%' from public.delivery_packages where id=current_setting('test.render_package')::uuid),'text package has no irrelevant image slices');
select ok((select snapshot->'links'->>0 like '%utm_campaign=%' from public.delivery_packages where id=current_setting('test.render_package')::uuid),'campaign UTM persists in immutable destination map');
select is((select count(*) from public.design_renders),2::bigint,'section revisions retain prior renders');
select throws_ok($$select public.save_own_template('00000000-0000-4000-8000-000000000102',gen_random_uuid())$$,'23514',null,'unsent design cannot become a confirmed-send template');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.design_renders),0::bigint,'other tenant cannot see private renders');
select throws_ok($$select public.review_render('00000000-0000-4000-8000-000000000102',current_setting('test.render_id2')::uuid,4,'approved','whole_design','Approve')$$,'42501',null,'other tenant cannot review render');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.own_templates),0::bigint,'designer cannot enumerate tenant templates');
select is((select count(*) from public.design_renders),0::bigint,'designer cannot enumerate generated renders');
select throws_ok($$select public.enqueue_render('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000602',2,4)$$,'42501',null,'designer cannot execute owner fixture path');

select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.approve_calendar('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1);
select public.save_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1,'{"subject":"Original field note","preheader":"Fixture","body":"Explore the verified item.","cta":"Explore","url":"https://cedar-lane.example/products/overshirt"}');
select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2);
select throws_ok($$select public.enqueue_render('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,2)$$,'23514',null,'unapproved kit blocks image rendering');
reset role;
insert into public.brand_kits(tenant_id,colors,fonts,approved_by) values('00000000-0000-4000-8000-000000000101',array['#123abc'],array['Inter'],'00000000-0000-4000-8000-000000000001');
insert into storage.objects(bucket_id,name) values('brand-assets','00000000-0000-4000-8000-000000000101/metadata-fixture.png');
insert into public.assets(id,tenant_id,storage_path,filename,sha256,media_type,byte_size,source,category,uploaded_by,synthetic) values('00000000-0000-4000-8000-000000000701','00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000101/metadata-fixture.png','Original synthetic metadata.png',repeat('d',64),'image/png',100,'upload','logo','00000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('test.image_job',public.enqueue_render('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,2)::text,true);
select set_config('test.image_lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000101')),true);
select throws_ok($$select public.finish_render_job(current_setting('test.image_job')::uuid,current_setting('test.image_lease')::uuid,'{"synthetic":true,"strips":[{"section":"hero","path":"unverified.svg"},{"section":"copy","path":"missing.svg"},{"section":"cta","path":"foreign.svg"}]}')$$,'23514',null,'missing or foreign strip proofs block submission');
reset role;
insert into storage.objects(bucket_id,name) select 'email-artifacts','00000000-0000-4000-8000-000000000101/'||current_setting('test.image_job')||'/'||repeat(x,64)||'.svg' from unnest(array['a','b','c']) x;
select public.record_render_upload(current_setting('test.image_job')::uuid,current_setting('test.image_lease')::uuid,'00000000-0000-4000-8000-000000000101/'||current_setting('test.image_job')||'/'||repeat(x,64)||'.svg',s,repeat(x,64),100) from (values('a','hero'),('b','copy'),('c','cta')) as strips(x,s);
set local role authenticated;
select set_config('test.image_render',public.finish_render_job(current_setting('test.image_job')::uuid,current_setting('test.image_lease')::uuid,jsonb_build_object('synthetic',true,'strips',(select jsonb_agg(jsonb_build_object('section',s,'path','00000000-0000-4000-8000-000000000101/'||current_setting('test.image_job')||'/'||repeat(x,64)||'.svg','copyRevision',2)) from (values('a','hero'),('b','copy'),('c','cta')) as strips(x,s))))::text,true);
select public.review_render('00000000-0000-4000-8000-000000000101',current_setting('test.image_render')::uuid,3,'approved','whole_design','Owner exact approval');

select set_config('test.image_package',public.create_delivery_package('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',3,'{"senderName":"Synthetic Cedar","senderEmail":"studio@cedar-lane.example","address":"Original Fictional Postal Address","unsubscribeUrl":"https://cedar-lane.example/unsubscribe","privacyUrl":"https://cedar-lane.example/privacy"}')::text,true);
select public.enqueue_delivery('00000000-0000-4000-8000-000000000101',current_setting('test.image_package')::uuid,4);
select throws_ok($$select public.correct_asset('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000701',1,'proof')$$,'23514',null,'active delivery blocks used-asset correction');
reset role;
select throws_ok($$update public.brand_kits set revision=revision+1 where tenant_id='00000000-0000-4000-8000-000000000101'$$,'23514',null,'active delivery blocks used-kit changes');
-- Metadata fixture teardown: no provider record was prepared or sent.
update public.campaigns set delivery_state='ready' where id='00000000-0000-4000-8000-000000000601';
set local role authenticated;
select public.correct_asset('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000701',1,'proof');
select is((select design_state from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'unassigned','corrected asset invalidates affected design approval');
select is((select design_revision from public.campaigns where id='00000000-0000-4000-8000-000000000601'),4,'source correction bumps design revision');
select throws_ok($$select public.review_render('00000000-0000-4000-8000-000000000101',current_setting('test.image_render')::uuid,3,'approved','whole_design','Owner approval')$$,'PT409',null,'old approved source cannot be approved again after correction');
select * from finish();rollback;
